jellyBall.customCSS:
/* 步骤 1: 设置球体背景 (可选, 修改颜色) */
#floating-jellyfish-ball {
  background: rgba(173, 216, 230, 0.7); /* 淡蓝色背景 */
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  border: 1px solid rgba(173, 216, 230, 0.9);
  font-size: 0; /* 隐藏原始图标 */
}
body.dark-mode #floating-jellyfish-ball {
  background: rgba(70, 130, 180, 0.7); /* 深钢蓝色背景 */
  border-color: rgba(135, 206, 235, 0.5);
}

/* 步骤 2: 使用伪元素显示新的 Emoji */
#floating-jellyfish-ball::before {
  content: '💧'; /* 在这里替换为你想要的 Emoji */
  font-size: 28px; /* 在这里调整 Emoji 的大小 */
}

cssPresets.css:
#floating-jellyfish-ball {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;

  /* 调整图标大小和位置，使其居中 */
  font-size: 38px;
  line-height: 1;
  padding-top: 2px; /* 微调垂直居中 */
}

/* 步骤 2: 修改悬浮球内的图标 */
#floating-jellyfish-ball span {
  /* 使用 CSS content 替换图标，确保辉光效果正确应用 */
  display: block;
  font-size: 0; /* 隐藏原始的 🪼 图标 */
}
#floating-jellyfish-ball span::before {
  content: '💗'; /* 设置新图标为爱心 */
  font-size: 38px; /* 恢复图标大小 */
}

/* 步骤 3: 重新定义辉光动画，使其更适合爱心 */
@keyframes heart-glow {
  0% {
    filter: drop-shadow(0 0 4px rgba(255, 105, 180, 0.7));
  }
  50% {
    /* 使用 deep pink 实现更强的发光效果 */
    filter: drop-shadow(0 0 14px rgba(255, 20, 147, 1));
  }
  100% {
    filter: drop-shadow(0 0 4px rgba(255, 105, 180, 0.7));
  }
}

/* 步骤 4: 将新动画应用到辉光层 */
.jelly-ball-wrapper .jelly-ball-glow {
  /* 确保应用新的动画而不是旧的 */
  animation: heart-glow 2.5s infinite ease-in-out !important;
}

/* 步骤 5: (可选) 拖动时放大爱心，而不是整个球 */
#floating-jellyfish-ball.dragging {
  /* 覆盖原有的放大效果，直接放大图标本身 */
  transform: none !important;
}
#floating-jellyfish-ball.dragging span::before {
  transform: scale(1.15);
  display: block;
}
